public sealed class NativeBuffer : IDisposable
{
    private IntPtr _handle;
    private bool _disposed;

    public void Dispose()
    {
        if (_disposed) return;
        ReleaseHandle(_handle);
        _handle = IntPtr.Zero;
        _disposed = true;
        GC.SuppressFinalize(this);
    }

    ~NativeBuffer() => ReleaseHandle(_handle);

    private static void ReleaseHandle(IntPtr h) { /* P/Invoke */ }
}

